}
function drawStars(){
  for(const s of stars){
    s.y+=s.z*0.25;if(s.y>H)s.y-=H;
    const tw=0.5+0.5*Math.sin(game.titleTimer*3+s.tw);
    const c=s.z===3?PAL.white:s.z===2?PAL.cyan:PAL.grey;
    ctx.globalAlpha=0.3+0.7*tw;
    ctx.fillStyle=c;ctx.fillRect(s.x|0,s.y|0,s.z===3?1:1,s.z===3?1:1);
  }
