}
function text(str,x,y,color,size,align){
  ctx.font=size+'px monospace';ctx.textAlign=align||'center';ctx.fillStyle=color;
  ctx.fillText(str,x,y);
}
function drawHUD(){
  text('1UP',10,12,PAL.white,8,'left');
