  const denom=[1,5,10,20,30,50][(game.stage-1)%6];
  const x=W-16,y=H-14;
  ctx.fillStyle=denom>=50?PAL.purple:denom>=30?PAL.orange:denom>=20?PAL.cyan:denom>=10?PAL.green:denom>=5?PAL.yellow:PAL.white;
  ctx.fillRect(x,y,12,8);
  ctx.fillStyle='#000';text(String(denom),x+6,y+7,'#000',7);
  ctx.strokeStyle=PAL.white;ctx.strokeRect(x+0.5,y+0.5,11,7);
}
function drawPlayer(){
  if(player.invuln>0&&Math.floor(player.invuln*10)%2===0)return;
