  if(player.red)drawSprite(SP.player,player.x+6,player.y,2,false);
}
function drawEnemy(e){
  let spr;
  if(e.type==='boss')spr=e.hp===0?ENEMY_SPRITE.bossBlue[e.frame]:ENEMY_SPRITE.boss[e.frame];
  else if(e.type==='goei')spr=ENEMY_SPRITE.goei[e.frame];
  else spr=ENEMY_SPRITE.zaku[e.frame];
