function drawBeam(b){
  const bw=18+b.beamT*22;
  const grad=ctx.createLinearGradient(0,b.y,0,H);
  grad.addColorStop(0,hexA(PAL.blue,0.5));grad.addColorStop(1,hexA(PAL.cyan,0.15));
  ctx.fillStyle=grad;
  ctx.beginPath();ctx.moveTo(b.x-bw/2,b.y);ctx.lineTo(b.x+bw/2,b.y);
  ctx.lineTo(b.x+bw,H);ctx.lineTo(b.x-bw,H);ctx.closePath();ctx.fill();
  // animated stripes
  ctx.strokeStyle=hexA(PAL.cyan,0.6);
  for(let i=0;i<4;i++){const yy=b.y+((game.titleTimer*40+i*20)% (H-b.y));
    const ww=bw/2*((yy-b.y)/(H-b.y))+4;
    ctx.beginPath();ctx.moveTo(b.x-ww,yy);ctx.lineTo(b.x+ww,yy);ctx.stroke();}
}
function drawBullet(b){
  ctx.fillStyle=b.from==='player'?PAL.white:PAL.orange;
  ctx.fillRect(b.x-1,b.y-3,2,6);
}
function drawExplosion(x){
  const p=x.t/x.dur;const ring=Math.floor(p*x.frames);
  const cols=[PAL.white,PAL.yellow,PAL.orange,PAL.red];
  const r=3+p*10;
  ctx.fillStyle=cols[ring%cols.length];
  for(let i=0;i<8;i++){const a=i/8*6.28;
    ctx.fillRect(x.x+Math.cos(a)*r-1,x.y+Math.sin(a)*r-1,2,2);}
  if(ring<2){ctx.fillStyle=PAL.white;ctx.fillRect(x.x-2,x.y-2,4,4);}
}
function drawReady(){text('READY',W/2,H-40,PAL.yellow,8);}
function drawPause(){text('PAUSE',W/2,H/2,PAL.white,10);}
function drawTitle(){
  text('NAMCO',W/2,30,PAL.white,8);
