  const T='GALAGA';
  ctx.font='20px monospace';ctx.textAlign='center';
  for(let i=0;i<T.length;i++){
    const col=[PAL.red,PAL.orange,PAL.yellow,PAL.green,PAL.cyan,PAL.purple][i];
