  drawSprite(SP.boss,40,ty+34,2,false);text('150 PTS',120,ty+37,PAL.white,7,'left');
  text('STAGE BONUS',W/2,150,PAL.cyan,7);
  if(game.titleTimer>1&&Math.floor(game.titleTimer*2)%2===0)
    text('PRESS ENTER TO START',W/2,180,PAL.yellow,8);
