    if(b.from!=='player')continue;
    for(const e of enemies){
      if(e.dead||e.state==='pending')continue;
      if(Math.abs(b.x-e.x)<6&&Math.abs(b.y-e.y)<6){b.dead=true;game.hits++;destroyEnemy(e,false);break;}
    }
  }
  if(player&&player.alive&&player.invuln<=0){
    const hw=player.red?7:4;
    for(const b of bullets){if(b.from==='enemy'&&Math.abs(b.x-player.x)<hw+2&&Math.abs(b.y-player.y)<6){b.dead=true;killPlayer();break;}}
  }
  bullets=bullets.filter(b=>!b.dead);
  enemies=enemies.filter(e=>!e.dead);
}
function handleStart(){
